import React from 'react';

function App() {
  return (
    <div style={{ 
      display: 'flex', 
      justifyContent: 'center', 
      alignItems: 'center', 
      height: '100vh',
      fontFamily: 'Arial',
      flexDirection: 'column'
    }}>
      <h1 style={{ fontSize: '48px', color: '#2a7de1' }}>🌐 ISP Manager</h1>
      <p style={{ fontSize: '18px', color: '#666' }}>React is working!</p>
      <p style={{ fontSize: '14px', color: '#999', marginTop: '20px' }}>
        If you see this, the frontend is loading correctly.
      </p>
    </div>
  );
}

export default App;
